<div class="admin-page-head"><div><h1>服务类目</h1><p>一级类目和后续子项均来自数据库，停用不会影响历史订单</p></div></div>
<div class="admin-grid admin-grid--3">
<section class="admin-card" style="grid-column:span 2"><header class="admin-card__header"><h2 class="admin-card__title">类目列表</h2></header><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>排序</th><th>名称</th><th>业务编码</th><th>订单号字母码</th><th>上级</th><th>状态</th><th>操作</th></tr></thead><tbody><?php foreach($categories as $category): $meta=status_meta($category['status']); ?><tr><td><?= (int)$category['sort_order'] ?></td><td><strong><?= e($category['name']) ?></strong><small class="admin-table__secondary"><?= e($category['description']) ?></small></td><td class="admin-mono"><?= e($category['code']) ?></td><td class="admin-mono"><strong>BX<?= e($category['order_code']) ?>261011-K7M4Q9</strong></td><td><?= e($category['parent_name']?:'一级类目') ?></td><td><span class="admin-badge admin-badge--<?= e($meta[1]) ?>"><?= e($meta[0]) ?></span></td><td><div class="admin-inline-actions"><a class="admin-btn admin-btn--sm" href="<?= e(admin_url('categories',['id'=>$category['id']])) ?>"><i class="ri-edit-line"></i> 编辑</a><form method="post" action="<?= e(admin_url('categories.toggle',['id'=>$category['id']])) ?>"><?= csrf()->input() ?><button class="admin-btn admin-btn--sm" data-confirm="确认切换类目状态？"><?= $category['status']==='active'?'停用':'启用' ?></button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="admin-card"><header class="admin-card__header"><h2 class="admin-card__title"><?= $editing?'编辑类目':'新增类目' ?></h2></header><form class="admin-card__body admin-form-grid" method="post" action="<?= e(admin_url('categories.save')) ?>"><?= csrf()->input() ?><input type="hidden" name="id" value="<?= (int)($editing['id']??0) ?>"><div class="admin-field admin-field--full"><label class="admin-label">类目名称 <span class="admin-required">*</span></label><input class="admin-control" name="name" required value="<?= e($editing['name']??'') ?>"></div><div class="admin-field admin-field--full"><label class="admin-label">唯一业务编码</label><input class="admin-control" name="code" required pattern="[A-Za-z0-9_-]{2,50}" value="<?= e($editing['code']??'') ?>"></div><div class="admin-field admin-field--full"><label class="admin-label">订单号字母码</label><div class="admin-input-wrap"><span class="admin-input-prefix">BX</span><input class="admin-control admin-mono" name="order_code" required pattern="[A-Z]{2}" minlength="2" maxlength="2" value="<?= e($editing['order_code']??'QT') ?>"></div><p class="admin-help">墙布用 QB、墙纸用 QZ；编号格式为 BX + 两位类目码 + 六位日期 + 六位随机码，例如 BXQB261011-K7M4Q9；历史单号不变。</p></div><div class="admin-field admin-field--full"><label class="admin-label">上级类目</label><select class="admin-control" name="parent_id"><option value="0">一级类目</option><?php foreach($categories as $parent): if($parent['parent_id']!==null)continue; ?><option value="<?= (int)$parent['id'] ?>" <?= (int)($editing['parent_id']??0)===(int)$parent['id']?'selected':'' ?>><?= e($parent['name']) ?></option><?php endforeach; ?></select></div><div class="admin-field"><label class="admin-label">排序</label><input class="admin-control" name="sort_order" type="number" value="<?= e($editing['sort_order']??0) ?>"></div><div class="admin-field admin-field--full"><label class="admin-label">说明</label><textarea class="admin-control" name="description"><?= e($editing['description']??'') ?></textarea></div><button class="admin-btn admin-btn--primary" type="submit"><i class="ri-save-line"></i> 保存类目</button></form></section>
